"use strict";
// Mechanical atlas extraction/registration only; artwork is generated by image_gen.
const fs=require("node:fs"),path=require("node:path"),assert=require("node:assert/strict");
const sharp=require(process.env.GRIDSHARD_SHARP_MODULE||"sharp");
const root=path.resolve(__dirname,".."),size=128;
function components(data,width,height){
  const seen=new Uint8Array(width*height),queue=new Int32Array(width*height),found=[];
  for(let start=0;start<seen.length;start++){
    if(seen[start]||data[start*4+3]<128)continue;
    let read=0,write=1;queue[0]=start;seen[start]=1;
    let minX=width,minY=height,maxX=0,maxY=0,sumX=0,sumY=0;
    while(read<write){
      const p=queue[read++],x=p%width,y=Math.floor(p/width);
      minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);sumX+=x;sumY+=y;
      for(const n of [x>0?p-1:-1,x<width-1?p+1:-1,y>0?p-width:-1,y<height-1?p+width:-1]){
        if(n>=0&&!seen[n]&&data[n*4+3]>=128){seen[n]=1;queue[write++]=n;}
      }
    }
    if(write>2000)found.push({left:minX,top:minY,width:maxX-minX+1,height:maxY-minY+1,count:write,cx:sumX/write,cy:sumY/write});
  }
  return found.sort((a,b)=>b.count-a.count).slice(0,8);
}
async function main(){
  const manifest=JSON.parse(fs.readFileSync(path.join(root,"docs/MODUL_KAMERA_V13_PROMPTLARI_20261017.json"),"utf8"));
  const dir=path.join(root,"client/assets/ui/modules-views-v3");fs.mkdirSync(dir,{recursive:true});
  const dataOut={},records=[],preview=[];
  for(const asset of manifest.assets){
    const raw=await sharp(asset.source).ensureAlpha().raw().toBuffer({resolveWithObject:true});
    const width=raw.info.width,height=raw.info.height;
    const pieces=components(raw.data,width,height);assert.equal(pieces.length,8,asset.id+": eight independent whole devices");
    const cells=Array(8);
    for(const piece of pieces){const i=Math.min(1,Math.floor(piece.cy/(height/2)))*4+Math.min(3,Math.floor(piece.cx/(width/4)));assert.ok(!cells[i],asset.id+": two objects in a cell");cells[i]=piece;}
    assert.ok(cells.every(Boolean));
    const grounds=cells.map(c=>{
      let sum=0,n=0;
      for(let y=c.top+Math.floor(c.height*.8);y<c.top+c.height;y++)for(let x=c.left;x<c.left+c.width;x++)if(raw.data[(y*width+x)*4+3]>128){sum+=x;n++;}
      return {x:n?sum/n:c.cx,y:c.top+c.height*.9};
    });
    // Uniform scale for ALL views, accounting for asymmetric arms/barrels.
    const scale=Math.min(...cells.flatMap((c,i)=>{
      const p=grounds[i];return [56/(p.x-c.left+3),56/(c.left+c.width+3-p.x),97/(p.y-c.top+3),18/(c.top+c.height+3-p.y)];
    }));
    const composites=[],frames=[];
    for(let i=0;i<8;i++){
      const c=cells[i],crop={left:Math.max(0,c.left-3),top:Math.max(0,c.top-3),width:Math.min(width-c.left+3,c.width+6),height:Math.min(height-c.top+3,c.height+6)};
      crop.width=Math.min(crop.width,width-crop.left);crop.height=Math.min(crop.height,height-crop.top);
      const pivot=grounds[i];
      const w=Math.max(1,Math.round(crop.width*scale)),h=Math.max(1,Math.round(crop.height*scale));
      const left=Math.round(size*.5-(pivot.x-crop.left)*scale),top=Math.round(size*.82-(pivot.y-crop.top)*scale);
      assert.ok(left>=0&&top>=0&&left+w<=size&&top+h<=size,asset.id+": whole frame must fit");
      const frame=await sharp(asset.source).extract(crop).resize(w,h).png().toBuffer();
      composites.push({input:frame,left:(i%4)*size+left,top:Math.floor(i/4)*size+top});
      const p=asset.sourceEmitters?.[i];
      const emitter=p?{x:(left+(p[0]-crop.left)*scale)/size,y:(top+(p[1]-crop.top)*scale)/size}:{x:.5,y:.5};
      const pair=asset.sourcePairs?.[i]?.map(p=>({x:(left+(p[0]-crop.left)*scale)/size,y:(top+(p[1]-crop.top)*scale)/size}));
      assert.ok(emitter.x>=0&&emitter.x<=1&&emitter.y>=0&&emitter.y<=1,asset.id+": emitter in frame");
      frames.push({crop,left,top,width:w,height:h,sourceGround:pivot,emitter,pair});
    }
    const atlas=await sharp({create:{width:size*4,height:size*2,channels:4,background:"#00000000"}}).composite(composites).webp({quality:90,alphaQuality:100,effort:6}).toBuffer();
    fs.writeFileSync(path.join(dir,asset.id+".webp"),atlas);
    dataOut[asset.id]={emitters:frames.map(f=>f.emitter),...(asset.sourcePairs?{pairs:frames.map(f=>f.pair)}:{})};
    records.push({id:asset.id,bytes:atlas.length,width:size*4,height:size*2,scale,frames});
    const front=await sharp(atlas).extract({left:2*size,top:0,width:size,height:size}).png().toBuffer();
    const index=records.length-1;preview.push({input:front,left:(index%5)*160+16,top:Math.floor(index/5)*170+55});
    const name={laser:"Lazer",shield:"Kalkan",battery:"Batarya",amplifier:"Güçlendirici",emp:"EMP",repair:"Onarım",armor:"Sönümleyici",cooler:"Soğutucu",pulse_cannon:"Darbe Topu",missile_launcher:"Füze"}[asset.id];
    preview.push({input:Buffer.from(`<svg width="160" height="24"><text x="80" y="17" text-anchor="middle" fill="#e0f5fa" font-family="Arial" font-size="14">${name}</text></svg>`),left:(index%5)*160,top:Math.floor(index/5)*170+180});
  }
  // Generated registration table; no fetch or per-shot asset loading.
  fs.writeFileSync(path.join(root,"client/src/module-view-data.js"),`/* Generated by tools/prepare-module-views-v13.cjs. */\nglobalThis.GridshardModuleViewData = Object.freeze(${JSON.stringify(dataOut,null,2)});\n`);
  const out=path.join(root,"artifacts/modules-camera-v13-20261017");fs.mkdirSync(out,{recursive:true});
  preview.push({input:Buffer.from('<svg width="800" height="45"><text x="400" y="24" text-anchor="middle" fill="#75e7cf" font-family="Arial" font-size="18">DİK GÖVDELER · 8 YÖN · VARLIK ÖNİZLEMESİ</text></svg>'),left:0,top:0});
  await sharp({create:{width:800,height:390,channels:4,background:"#0a202b"}}).composite(preview).webp({quality:90}).toFile(path.join(out,"upright-modules-preview.webp"));
  const report={date:"2026-10-17",cameraDegreesFromOverhead:30,viewCount:8,targetMathContinuous:true,volumetric3D:false,totalBytes:records.reduce((n,r)=>n+r.bytes,0),files:records};
  fs.writeFileSync(path.join(root,"qa_reports/modules-camera-v13-assets-20261017.json"),JSON.stringify(report,null,2)+"\n");
  console.log(JSON.stringify({modules:records.length,bytes:report.totalBytes,preview:path.join(out,"upright-modules-preview.webp")}));
}
main().catch(e=>{console.error(e);process.exitCode=1;});
